import sys

def median(arr):
    sorted_arr = sorted(arr)
    n = len(sorted_arr)
    return sorted_arr[(n - 1) // 2]

def solve():
    T = int(sys.stdin.readline())
    for _ in range(T):
        N = int(sys.stdin.readline())
        if N == 2:
            print("2 1")
        else:
            permutation = [2] + [1] + list(range(3, N+1))
            print(' '.join(map(str, permutation)))

solve()
